document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll("a[href]");e.forEach(function(e){var n,t=e.getAttribute("href");if(!t||t.charAt(0)==="#")return;if(t.indexOf("mailto:")===0||t.indexOf("tel:")===0||t.indexOf("javascript:")===0)return;if(n=new URL(t,window.location.origin),n.origin===window.location.origin){e.removeAttribute("target"),e.removeAttribute("rel");return}e.setAttribute("target","_blank"),e.setAttribute("rel","noopener noreferrer")})})